import{_ as a,o,c as t,a2 as n}from"./chunks/framework.CHX4lV2z.js";const u=JSON.parse('{"title":"Uninstall and Rollback","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/uninstall-and-rollback.md","filePath":"user-guide/uninstall-and-rollback.md","lastUpdated":1791002220000}'),l={name:"user-guide/uninstall-and-rollback.md"};function i(r,e,s,d,c,p){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="uninstall-and-rollback" tabindex="-1">Uninstall and Rollback <a class="header-anchor" href="#uninstall-and-rollback" aria-label="Permalink to &quot;Uninstall and Rollback&quot;">​</a></h1><p>How to stop TokenPilot and restore your original configuration.</p><h2 id="quick-rollback" tabindex="-1">Quick Rollback <a class="header-anchor" href="#quick-rollback" aria-label="Permalink to &quot;Quick Rollback&quot;">​</a></h2><p>The OpenClaw, Codex, and Claude Code installers create <code>.tokenpilot.bak</code> backups for the host configuration files they preserve. Restore the applicable backup to its original name.</p><h2 id="pi-and-opencode" tabindex="-1">pi and OpenCode <a class="header-anchor" href="#pi-and-opencode" aria-label="Permalink to &quot;pi and OpenCode&quot;">​</a></h2><p>The pi and OpenCode adapters use their own package uninstall commands rather than the <code>.tokenpilot.bak</code> workflow. For pi, <code>npm --prefix components/adapters/pi run uninstall:pi</code> removes the extension loader and restores any loader file it backed up; add <code>-- --purge</code> to also delete the created config and state. For OpenCode, <code>npm --prefix components/adapters/opencode run uninstall:opencode</code> removes the plugin loader and exactly the <code>mcp.tokenpilot_memory_fault_recover</code> entry it added; add <code>-- --purge</code> to also delete the created config and state. See the <a href="/LightRSI/hosts/pi">pi</a> and <a href="/LightRSI/hosts/opencode">OpenCode</a> host guides.</p><h2 id="deepseek-harness" tabindex="-1">DeepSeek Harness <a class="header-anchor" href="#deepseek-harness" aria-label="Permalink to &quot;DeepSeek Harness&quot;">​</a></h2><p>DeepSeek Harness uses its own Cordis profile installation. The <code>.tokenpilot.bak</code> workflow above does not apply. To stop the adapter&#39;s automatic eviction, set <code>eviction.enabled</code> to <code>false</code> in its profile configuration, or set the plugin&#39;s <code>enabled</code> to <code>false</code> to disable its eviction handler. Reload the configured profile. This stops future changes; it does not undo prior replacements. See <a href="/LightRSI/hosts/deepseek-harness#configure-and-enable">DeepSeek Harness configuration</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/LightRSI/getting-started/install-lightrsi">Install LightRSI</a> — fresh install</li><li><a href="/LightRSI/plugin-catalog/tokenpilot/troubleshooting">Troubleshooting</a> — problems before uninstalling</li></ul>',10)])])}const k=a(l,[["render",i]]);export{u as __pageData,k as default};
